//! Experimental: a product worker compiled to wasm, run in the core.
//!
//! The worker is bound to one product. Each `truapi` import it declares is
//! linked to a typed call on that product's [`TrUApi`] implementation, as
//! generated by `#[wasm_env]` on every service trait, so a worker reaches the
//! core in process with no frames in between. The import names and the guest
//! protocol are in [`crate::wasm_abi`].
//!
//! The host starts its own calls into the worker through [`HostCalls`]. As
//! the product of a [`crate::ProductRuntime`], the worker gets the
//! host-initiated calls of that connection; see
//! [`WasmWorker::for_product_runtime`].
//!
//! The host stops a worker through a [`WorkerStop`]. A worker that exports
//! [`ON_STOP_EXPORT`] then gets a short time to write what it holds in memory
//! before it ends; see [`WasmWorker::stopper`].

mod host_calls;
mod product;

pub use host_calls::{HostCall, HostCallEvent, HostCallStream, HostCalls};

use core::{
	task::{Context, Poll},
	time::Duration,
};
use std::{
	collections::{BTreeMap, BTreeSet, HashMap},
	sync::{
		Arc,
		atomic::{AtomicBool, Ordering},
	},
};

use futures::{
	FutureExt, StreamExt,
	channel::mpsc,
	future::BoxFuture,
	stream::{self, BoxStream},
	task::AtomicWaker,
};
use parity_scale_codec::{DecodeAll, Encode};
use wasmi::{
	Caller, Config, Engine, Extern, Linker, Memory, Module, Store, StoreLimits, StoreLimitsBuilder,
	TypedFunc,
};

use crate::{
	CallContext, CallError, CancellationToken, Subscription,
	api::TrUApi,
	frame::downgrade_call_error,
	versioned::{FromLatest, IntoLatest, Versioned},
	wasm_abi::{
		CALL_END_IMPORT, CALL_ITEM_IMPORT, EventKind, FINISH_IMPORT, IMPORT_MODULE, LOG_IMPORT,
		MONOTONIC_MILLIS_IMPORT, NOW_MILLIS_IMPORT, ON_CALL_EXPORT, ON_CANCEL_EXPORT,
		ON_EVENT_EXPORT, ON_STOP_EXPORT, RANDOM_IMPORT, READ_EVENT_IMPORT, RELEASE_IMPORT,
		SLEEP_IMPORT, START_EXPORT,
	},
};
use host_calls::{Answers, HostCommand, worker_ended};

/// Default fuel of one entry from the host, about one fuel unit for each wasm
/// instruction. An entry is the start of the worker or the delivery of one
/// event. The value is high for crypto and database work in one entry, such as
/// X448, sntrup761 and an encrypted SQLite image. A release build uses about 400 million fuel
/// each second, so a worker in an endless loop traps after about 50 seconds.
/// [`WasmWorker::with_fuel_per_entry`] changes it.
pub const DEFAULT_FUEL_PER_ENTRY: u64 = 20_000_000_000;

/// How the engine compiles a module. A product worker is large (several MB,
/// most of it SQLite and crypto that a start does not run), and lazy
/// compilation compiles and validates a function only before its first call.
/// Thus a worker starts without a compilation of the whole module. A function
/// that is not valid traps at its first call, and the trap ends the worker as
/// any other trap does.
const COMPILATION_MODE: wasmi::CompilationMode = wasmi::CompilationMode::Lazy;

/// Default limit of the linear memory of a worker: 256 MiB. The engine
/// gets memory only when the worker grows it, so a high limit costs nothing.
/// [`WasmWorker::with_memory_limit`] changes it.
pub const DEFAULT_MEMORY_LIMIT: usize = 256 * 1024 * 1024;

/// Default time that a stopped worker gets to end by itself: see
/// [`WasmWorker::stopper`]. [`WasmWorker::with_stop_grace`] changes it.
pub const DEFAULT_STOP_GRACE: Duration = Duration::from_secs(2);

/// Largest request or log line a worker may pass, matching the frame cap of
/// the native WebSocket bridge.
const MAX_PAYLOAD_BYTES: u32 = 8 << 20;

/// Calls a worker may hold open at once.
const MAX_CALLS_IN_FLIGHT: usize = 1024;

/// Linear memory export every worker declares.
const MEMORY_EXPORT: &str = "memory";

/// Why a wasm worker could not load or stopped.
#[derive(Debug, derive_more::Display, derive_more::Error)]
pub enum WasmWorkerError {
	/// The bytes are not a valid module, or instantiating it failed.
	#[display("invalid module: {reason}")]
	InvalidModule {
		/// What the engine rejected.
		reason: String,
	},
	/// The module imports a function the host does not provide.
	#[display("unknown import `{module}.{name}`")]
	UnknownImport {
		/// Import module.
		module: String,
		/// Import name.
		name: String,
	},
	/// The module trapped, ran out of fuel, or broke the guest protocol.
	#[display("worker trapped: {reason}")]
	Trapped {
		/// Engine diagnostic.
		reason: String,
	},
	/// The entry point is waiting on nothing the host will ever answer, and
	/// the host can start no call into the worker.
	#[display("worker is waiting with no call in flight")]
	Stalled,
	/// The entry point returned an error.
	#[display("worker failed: {message}")]
	Failed {
		/// Error the guest reported.
		message: String,
	},
	/// The host stopped the worker through its [`WorkerStop`].
	#[display("the host stopped the worker")]
	Stopped,
}

/// A handle that stops a [`WasmWorker`]. It can stop the worker before it
/// runs, while it runs, and after it ended (then it does nothing).
#[derive(Clone, Default)]
pub struct WorkerStop {
	inner: Arc<StopState>,
}

#[derive(Default)]
struct StopState {
	requested: AtomicBool,
	waker: AtomicWaker,
}

impl WorkerStop {
	/// A handle that no worker uses yet. Give it to
	/// [`WasmWorker::with_stopper`].
	pub fn new() -> Self {
		Self::default()
	}

	/// Ask the worker to stop. A worker that exports [`ON_STOP_EXPORT`] gets
	/// the stop and runs until it ends or until its grace time ends. Any
	/// other worker ends at once.
	pub fn stop(&self) {
		self.inner.requested.store(true, Ordering::Release);
		self.inner.waker.wake();
	}

	/// Whether a stop was asked.
	pub fn is_requested(&self) -> bool {
		self.inner.requested.load(Ordering::Acquire)
	}

	fn poll_requested(&self, context: &mut Context<'_>) -> bool {
		self.inner.waker.register(context.waker());
		self.is_requested()
	}
}

impl From<wasmi::Error> for WasmWorkerError {
	fn from(error: wasmi::Error) -> Self {
		Self::Trapped { reason: error.to_string() }
	}
}

struct Event {
	kind: EventKind,
	payload: Vec<u8>,
}

type Method = Arc<dyn Fn(CallContext, Vec<u8>) -> BoxStream<'static, Event> + Send + Sync>;

/// The `truapi` imports a worker can link against, each bound to `H`.
pub struct WasmEnv<H> {
	host: Arc<H>,
	methods: HashMap<&'static str, Method>,
	excluded: BTreeSet<&'static str>,
}

impl<H: Send + Sync + 'static> WasmEnv<H> {
	/// An environment with no methods linked.
	pub fn new(host: Arc<H>) -> Self {
		Self { host, methods: HashMap::new(), excluded: BTreeSet::new() }
	}

	/// Names of the linked methods.
	pub fn method_names(&self) -> impl Iterator<Item = &'static str> + '_ {
		self.methods.keys().copied()
	}

	/// Record a method of a linked trait that a worker cannot start. The
	/// host starts it, or it is internal. It gets no import.
	pub fn exclude(&mut self, name: &'static str) {
		self.excluded.insert(name);
	}

	/// Names of the methods that the linked traits keep from a worker.
	pub fn excluded_names(&self) -> impl Iterator<Item = &'static str> + '_ {
		self.excluded.iter().copied()
	}

	/// Link a request method, answering in the caller's protocol version.
	pub fn request<Request, Response, Error, Handler>(
		&mut self,
		name: &'static str,
		handler: Handler,
	) where
		Request: DecodeAll + Versioned,
		Response: Encode + FromLatest + IntoLatest + Send + 'static,
		Error: Encode + FromLatest + IntoLatest + Send + 'static,
		Handler: Fn(
				Arc<H>,
				CallContext,
				Request,
			) -> BoxFuture<'static, Result<Response, CallError<Error>>>
			+ Send
			+ Sync
			+ 'static,
	{
		let host = self.host.clone();
		let method: Method = Arc::new(move |cx, payload| {
			let result: BoxFuture<'static, Result<Response, CallError<Error>>> =
				match decode_request::<Request, Error>(&payload) {
					Ok(request) => {
						let target = request.version();
						handler(host.clone(), cx, request)
							.map(move |result| {
								result
									.map(|response| {
										Response::from_latest(response.into_latest(), target)
									})
									.map_err(|error| downgrade_call_error(error, target))
							})
							.boxed()
					},
					Err(error) => futures::future::ready(Err(error)).boxed(),
				};
			stream::once(
				result.map(|result| Event { kind: EventKind::Response, payload: result.encode() }),
			)
			.boxed()
		});
		self.methods.insert(name, method);
	}

	/// Link a subscription method, streaming in the caller's protocol version.
	pub fn subscription<Request, Item, Error, Handler>(
		&mut self,
		name: &'static str,
		handler: Handler,
	) where
		Request: DecodeAll + Versioned,
		Item: Encode + FromLatest + IntoLatest + Send + 'static,
		Error: Encode + FromLatest + IntoLatest + Send + 'static,
		Handler: Fn(
				Arc<H>,
				CallContext,
				Request,
			) -> BoxFuture<'static, Subscription<Item, CallError<Error>>>
			+ Send
			+ Sync
			+ 'static,
	{
		let host = self.host.clone();
		let method: Method =
			Arc::new(move |cx, payload| match decode_request::<Request, Error>(&payload) {
				Ok(request) => {
					let target = request.version();
					// The guest releases a subscription when it drops it. Then the
					// subscription ends at once, also when its stream does not
					// watch the cancellation. The worker forgets the call at
					// that end and drops the stream, which frees the resources
					// of the host, for example a remote chain head follow.
					let token = cx.cancel().clone();
					let cancelled = token.cancelled();
					let released = stream::once(async move {
						token.is_cancelled().then(|| end_event::<Error>(Ok(())))
					})
					.filter_map(futures::future::ready);
					stream::once(handler(host.clone(), cx, request))
						.flat_map(move |subscription| subscription_events(subscription, target))
						.take_until(cancelled)
						.chain(released)
						.boxed()
				},
				Err(error) => stream::once(futures::future::ready(end_event(Err(error)))).boxed(),
			});
		self.methods.insert(name, method);
	}
}

impl<H: TrUApi + 'static> WasmEnv<H> {
	/// Every method a product may start, bound to `host`.
	pub fn for_product(host: Arc<H>) -> Self {
		let mut env = Self::new(host);
		env.link_system();
		env.link_account();
		env.link_chain();
		env.link_chat();
		env.link_coin_payment();
		env.link_contacts();
		env.link_entropy();
		env.link_expanded_card();
		env.link_game();
		env.link_local_storage();
		env.link_locale();
		env.link_notifications();
		env.link_payment();
		env.link_permissions();
		env.link_pocket();
		env.link_preimage();
		env.link_renderer();
		env.link_resource_allocation();
		env.link_scanner();
		env.link_share();
		env.link_usernames();
		env.link_signing();
		env.link_statement_store();
		env.link_theme();
		env.link_worker();
		env
	}
}

fn decode_request<Request: DecodeAll, Error>(payload: &[u8]) -> Result<Request, CallError<Error>> {
	Request::decode_all(&mut &payload[..])
		.map_err(|error| CallError::MalformedFrame { reason: error.to_string() })
}

fn end_event<Error: Encode>(end: Result<(), CallError<Error>>) -> Event {
	Event { kind: EventKind::End, payload: end.encode() }
}

/// Items of `subscription`, then exactly one end event.
fn subscription_events<Item, Error>(
	subscription: Subscription<Item, CallError<Error>>,
	target: u8,
) -> impl futures::Stream<Item = Event>
where
	Item: Encode + FromLatest + IntoLatest,
	Error: Encode + FromLatest + IntoLatest,
{
	stream::unfold(Some(subscription), move |subscription| async move {
		let mut subscription = subscription?;
		let event = match subscription.next().await {
			Some(Ok(item)) => Event {
				kind: EventKind::Item,
				payload: Item::from_latest(item.into_latest(), target).encode(),
			},
			Some(Err(error)) => {
				return Some((end_event(Err(downgrade_call_error(error, target))), None));
			},
			None => return Some((end_event::<Error>(Ok(())), None)),
		};
		Some((event, Some(subscription)))
	})
}

enum Command {
	Start { handle: u32, method: Method, request: Vec<u8> },
	Sleep { handle: u32, millis: u64 },
	Release { handle: u32 },
	Answer { call: u32, event: HostCallEvent },
}

struct GuestState {
	limits: StoreLimits,
	log: Box<dyn Fn(&str) + Send + Sync>,
	/// When the worker loaded, the zero of `monotonic_millis`.
	loaded: std::time::Instant,
	next_handle: u32,
	calls_in_flight: usize,
	commands: Vec<Command>,
	/// Payload of the event being delivered, until the guest reads it.
	event_payload: Vec<u8>,
	finished: Option<Result<(), String>>,
	/// The fuel that the entries before the current one used.
	fuel_used: u64,
	/// The fuel of each entry.
	fuel_per_entry: u64,
	/// Put the fuel used so far before each log line of the guest.
	log_fuel: bool,
}

struct Exports {
	start: TypedFunc<(), ()>,
	on_event: TypedFunc<(u32, u32, u32), ()>,
	/// The exports that take calls from the host. A module without them
	/// answers no call.
	host_calls: Option<HostCallExports>,
	/// The export that takes the stop. A module without it ends at once when
	/// the host stops it.
	on_stop: Option<TypedFunc<(), ()>>,
}

struct HostCallExports {
	on_call: TypedFunc<(u32, u32, u32), ()>,
	on_cancel: TypedFunc<u32, ()>,
}

struct Call {
	events: BoxStream<'static, Event>,
	cancel: CancellationToken,
	/// The guest no longer awaits the call. A request runs until it settles,
	/// and its events are dropped. A subscription ends at once (see
	/// [`WasmEnv::subscription`]).
	released: bool,
	/// A timer, which the host forgets at once when the guest releases it.
	timer: bool,
}

/// A loaded wasm worker. [`Self::run`] drives it until its entry point
/// returns. Dropping it cancels every call still in flight, and ends each
/// call of the host that it did not answer.
pub struct WasmWorker {
	store: Store<GuestState>,
	exports: Exports,
	calls: BTreeMap<u32, Call>,
	/// Handle polling starts from, so one busy call cannot starve the rest.
	cursor: u32,
	fuel_per_entry: u64,
	/// The handle [`Self::host_calls`] gives out. The worker drops it when it
	/// starts to run, so that the inbox closes with the host's last handle.
	host_calls: Option<HostCalls>,
	inbox: mpsc::UnboundedReceiver<HostCommand>,
	inbox_closed: bool,
	/// The calls of the host that the worker did not end, by call id.
	answering: HashMap<u32, Answers>,
	stop: WorkerStop,
	stop_grace: Duration,
	/// The end of the grace time, after the guest got the stop.
	stopping: Option<futures_timer::Delay>,
}

/// What the worker does next.
enum Next {
	/// Deliver an event to one of the worker's calls.
	Event(u32, Event),
	/// Start or stop a call of the host.
	Host(HostCommand),
	/// No handle of the host is left.
	InboxClosed,
	/// The host asked the worker to stop.
	Stop,
	/// The grace time of a stop ended.
	StopTimeout,
}

impl WasmWorker {
	/// Instantiate `wasm` against `env`. Fails before running anything when
	/// the module imports a function `env` does not link.
	pub fn new<H: Send + Sync + 'static>(
		env: WasmEnv<H>,
		wasm: &[u8],
	) -> Result<Self, WasmWorkerError> {
		let mut config = Config::default();
		config.consume_fuel(true);
		config.compilation_mode(COMPILATION_MODE);
		let engine = Engine::new(&config);
		let compiling = std::time::Instant::now();
		let module = Module::new(&engine, wasm).map_err(invalid_module)?;
		tracing::debug!(
			target: "truapi::wasm_worker",
			bytes = wasm.len(),
			millis = compiling.elapsed().as_millis() as u64,
			"wasm module compiled"
		);
		let linker = link(&engine, &module, &env.methods)?;

		let state = GuestState {
			limits: StoreLimitsBuilder::new().memory_size(DEFAULT_MEMORY_LIMIT).build(),
			log: Box::new(|line| tracing::info!(target: "truapi::wasm_worker", "{line}")),
			loaded: std::time::Instant::now(),
			next_handle: 0,
			calls_in_flight: 0,
			commands: Vec::new(),
			event_payload: Vec::new(),
			finished: None,
			fuel_used: 0,
			fuel_per_entry: DEFAULT_FUEL_PER_ENTRY,
			log_fuel: false,
		};
		let mut store = Store::new(&engine, state);
		store.limiter(|state| &mut state.limits);
		store.set_fuel(DEFAULT_FUEL_PER_ENTRY)?;
		let instance = linker
			.instantiate(&mut store, &module)
			.and_then(|instance| instance.start(&mut store))
			.map_err(invalid_module)?;
		instance
			.get_memory(&store, MEMORY_EXPORT)
			.ok_or_else(|| missing_export(MEMORY_EXPORT))?;
		let host_calls = match (
			instance.get_export(&store, ON_CALL_EXPORT),
			instance.get_export(&store, ON_CANCEL_EXPORT),
		) {
			(None, None) => None,
			_ => Some(HostCallExports {
				on_call: instance.get_typed_func(&store, ON_CALL_EXPORT).map_err(invalid_module)?,
				on_cancel: instance
					.get_typed_func(&store, ON_CANCEL_EXPORT)
					.map_err(invalid_module)?,
			}),
		};
		let on_stop = match instance.get_export(&store, ON_STOP_EXPORT) {
			None => None,
			Some(_) => {
				Some(instance.get_typed_func(&store, ON_STOP_EXPORT).map_err(invalid_module)?)
			},
		};
		let exports = Exports {
			start: instance.get_typed_func(&store, START_EXPORT).map_err(invalid_module)?,
			on_event: instance.get_typed_func(&store, ON_EVENT_EXPORT).map_err(invalid_module)?,
			host_calls,
			on_stop,
		};
		let (handle, inbox) = host_calls::channel();
		Ok(Self {
			store,
			exports,
			calls: BTreeMap::new(),
			cursor: 0,
			fuel_per_entry: DEFAULT_FUEL_PER_ENTRY,
			host_calls: Some(handle),
			inbox,
			inbox_closed: false,
			answering: HashMap::new(),
			stop: WorkerStop::new(),
			stop_grace: DEFAULT_STOP_GRACE,
			stopping: None,
		})
	}

	/// The handle that stops this worker. After [`WorkerStop::stop`], a
	/// worker that exports [`ON_STOP_EXPORT`] gets one call of it, and the
	/// host keeps answering its calls for the grace time
	/// ([`Self::with_stop_grace`]). [`Self::run`] then returns when the
	/// guest ends or when the grace time ends. A worker without the export
	/// ends at once. Either way the result is [`WasmWorkerError::Stopped`],
	/// unless the guest fails while it stops.
	pub fn stopper(&self) -> WorkerStop {
		self.stop.clone()
	}

	/// Use `stop` as the handle that stops this worker, in place of its own.
	pub fn with_stopper(mut self, stop: WorkerStop) -> Self {
		self.stop = stop;
		self
	}

	/// Set the time that a stopped worker gets to end by itself. The default
	/// is [`DEFAULT_STOP_GRACE`].
	pub fn with_stop_grace(mut self, grace: Duration) -> Self {
		self.stop_grace = grace;
		self
	}

	/// A handle that starts calls into this worker. The worker takes them
	/// while it runs, and waits for them while a handle is left.
	pub fn host_calls(&self) -> HostCalls {
		self.host_calls.clone().expect("a worker holds its handle until it runs")
	}

	/// Set the fuel of one entry from the host. The default is
	/// [`DEFAULT_FUEL_PER_ENTRY`]. An entry that uses all of it traps.
	pub fn with_fuel_per_entry(mut self, fuel: u64) -> Self {
		self.fuel_per_entry = fuel;
		self.store.data_mut().fuel_per_entry = fuel;
		self
	}

	/// With `on`, each log line of the guest starts with `fuel=<n> `, where
	/// `<n>` is the fuel that the worker used since it started. The fuel
	/// counts the executed instructions, so it measures the work of the
	/// guest independently of the load of the machine.
	pub fn with_fuel_in_log(mut self, on: bool) -> Self {
		self.store.data_mut().log_fuel = on;
		self
	}

	/// Set the limit in bytes of the worker's linear memory. The default is
	/// [`DEFAULT_MEMORY_LIMIT`]. A memory that the module declares larger
	/// than the limit stays as it is, but it cannot grow.
	pub fn with_memory_limit(mut self, bytes: usize) -> Self {
		self.store.data_mut().limits = StoreLimitsBuilder::new().memory_size(bytes).build();
		self
	}

	/// Send the worker's log lines to `log` instead of `tracing`.
	pub fn with_log(mut self, log: impl Fn(&str) + Send + Sync + 'static) -> Self {
		self.store.data_mut().log = Box::new(log);
		self
	}

	/// Run the entry point, answering its calls and starting the calls of the
	/// host, until it returns.
	pub async fn run(mut self) -> Result<(), WasmWorkerError> {
		self.host_calls = None;
		if self.stop.is_requested() {
			return Err(WasmWorkerError::Stopped);
		}
		self.store.set_fuel(self.fuel_per_entry)?;
		let started = self.exports.start.call(&mut self.store, ());
		self.count_fuel();
		started?;
		loop {
			self.apply_commands();
			if let Some(outcome) = self.store.data_mut().finished.take() {
				return match outcome {
					Ok(()) if self.stopping.is_some() => Err(WasmWorkerError::Stopped),
					Ok(()) => Ok(()),
					Err(message) => Err(WasmWorkerError::Failed { message }),
				};
			}
			// A stopped worker can wait on nothing. It then ends when its
			// grace time ends.
			if self.stopping.is_none() &&
				self.inbox_closed &&
				self.calls.values().all(|call| call.released)
			{
				return Err(WasmWorkerError::Stalled);
			}
			match futures::future::poll_fn(|context| self.poll_next(context)).await {
				Next::Event(handle, event) => self.deliver(handle, event)?,
				Next::Host(command) => self.host_command(command)?,
				Next::InboxClosed => self.inbox_closed = true,
				Next::Stop => {
					let Some(on_stop) = self.exports.on_stop else {
						return Err(WasmWorkerError::Stopped);
					};
					self.stopping = Some(futures_timer::Delay::new(self.stop_grace));
					self.enter(Vec::new(), |store| on_stop.call(store, ()))?;
				},
				Next::StopTimeout => return Err(WasmWorkerError::Stopped),
			}
		}
	}

	/// A stop first, then a call of the host, then the next event of a call
	/// of the worker.
	fn poll_next(&mut self, context: &mut Context<'_>) -> Poll<Next> {
		match &mut self.stopping {
			None if self.stop.poll_requested(context) => return Poll::Ready(Next::Stop),
			None => {},
			Some(grace) => {
				if grace.poll_unpin(context).is_ready() {
					return Poll::Ready(Next::StopTimeout);
				}
			},
		}
		if !self.inbox_closed &&
			let Poll::Ready(command) = self.inbox.poll_next_unpin(context)
		{
			return Poll::Ready(command.map_or(Next::InboxClosed, Next::Host));
		}
		self.poll_calls(context).map(|(handle, event)| Next::Event(handle, event))
	}

	/// Start or stop a call of the host in the guest.
	fn host_command(&mut self, command: HostCommand) -> Result<(), WasmWorkerError> {
		match command {
			HostCommand::Start { call, method, request, mut answers } => {
				let Some(exports) = &self.exports.host_calls else {
					answers(HostCallEvent::failure(CallError::Unsupported));
					return Ok(());
				};
				let on_call = exports.on_call;
				let lengths = (call, method.len() as u32, request.len() as u32);
				self.answering.insert(call, answers);
				let mut payload = method.into_bytes();
				payload.extend(request);
				self.enter(payload, |store| on_call.call(store, lengths))
			},
			HostCommand::Cancel { call } => {
				let Some(exports) = &self.exports.host_calls else {
					return Ok(());
				};
				if self.answering.remove(&call).is_none() {
					return Ok(());
				}
				let on_cancel = exports.on_cancel;
				self.enter(Vec::new(), |store| on_cancel.call(store, call))
			},
		}
	}

	/// The next event of a call the guest still awaits. Each call is polled
	/// once per round, starting after the last one that delivered.
	fn poll_calls(&mut self, context: &mut Context<'_>) -> Poll<(u32, Event)> {
		let handles: Vec<u32> = self
			.calls
			.range(self.cursor..)
			.chain(self.calls.range(..self.cursor))
			.map(|(handle, _)| *handle)
			.collect();
		let mut discarded = false;
		for handle in handles {
			let call = self.calls.get_mut(&handle).expect("listed above");
			let Poll::Ready(event) = call.events.poll_next_unpin(context) else {
				continue;
			};
			let released = call.released;
			let event =
				event.expect("a call is forgotten at its terminal event, before its stream ends");
			if event.kind != EventKind::Item {
				self.forget(handle);
			}
			if !released {
				self.cursor = handle.wrapping_add(1);
				return Poll::Ready((handle, event));
			}
			discarded = true;
		}
		if discarded {
			context.waker().wake_by_ref();
		}
		Poll::Pending
	}

	fn forget(&mut self, handle: u32) {
		if self.calls.remove(&handle).is_some() {
			self.store.data_mut().calls_in_flight -= 1;
		}
	}

	fn apply_commands(&mut self) {
		for command in core::mem::take(&mut self.store.data_mut().commands) {
			match command {
				Command::Start { handle, method, request } => {
					let cancel = CancellationToken::default();
					let cx = CallContext::with_parts(format!("wasm-{handle}"), cancel.clone());
					let call =
						Call { events: method(cx, request), cancel, released: false, timer: false };
					self.calls.insert(handle, call);
				},
				Command::Sleep { handle, millis } => {
					let delay =
						futures_timer::Delay::new(core::time::Duration::from_millis(millis));
					let elapsed =
						delay.map(|()| Event { kind: EventKind::Response, payload: Vec::new() });
					let call = Call {
						events: stream::once(elapsed).boxed(),
						cancel: CancellationToken::default(),
						released: false,
						timer: true,
					};
					self.calls.insert(handle, call);
				},
				Command::Release { handle } => {
					let Some(call) = self.calls.get_mut(&handle) else {
						continue;
					};
					if call.timer {
						self.forget(handle);
					} else {
						call.cancel.cancel();
						call.released = true;
					}
				},
				Command::Answer { call, event } => {
					let Some(answers) = self.answering.get_mut(&call) else {
						continue;
					};
					let ended = matches!(event, HostCallEvent::End(_));
					answers(event);
					if ended {
						self.answering.remove(&call);
					}
				},
			}
		}
	}

	fn deliver(&mut self, handle: u32, event: Event) -> Result<(), WasmWorkerError> {
		let length = event.payload.len() as u32;
		let on_event = self.exports.on_event;
		self.enter(event.payload, |store| on_event.call(store, (handle, event.kind as u32, length)))
	}

	/// Run one entry of the guest with a full tank of fuel, while `payload` is
	/// what `read_event` copies.
	fn enter(
		&mut self,
		payload: Vec<u8>,
		entry: impl FnOnce(&mut Store<GuestState>) -> Result<(), wasmi::Error>,
	) -> Result<(), WasmWorkerError> {
		self.store.data_mut().event_payload = payload;
		self.store.set_fuel(self.fuel_per_entry)?;
		let entered = entry(&mut self.store);
		self.count_fuel();
		self.store.data_mut().event_payload.clear();
		Ok(entered?)
	}

	/// Add the fuel of the entry that just ended to the fuel used.
	fn count_fuel(&mut self) {
		let left = self.store.get_fuel().unwrap_or(0);
		let state = self.store.data_mut();
		state.fuel_used = state.fuel_used.saturating_add(state.fuel_per_entry.saturating_sub(left));
	}
}

impl Drop for WasmWorker {
	fn drop(&mut self) {
		for call in self.calls.values() {
			call.cancel.cancel();
		}
		for (_, mut answers) in self.answering.drain() {
			answers(worker_ended());
		}
		self.inbox.close();
		while let Ok(command) = self.inbox.try_recv() {
			if let HostCommand::Start { mut answers, .. } = command {
				answers(worker_ended());
			}
		}
	}
}

fn invalid_module(error: wasmi::Error) -> WasmWorkerError {
	WasmWorkerError::InvalidModule { reason: error.to_string() }
}

fn missing_export(name: &str) -> WasmWorkerError {
	WasmWorkerError::InvalidModule { reason: format!("missing export `{name}`") }
}

/// Link exactly the imports `module` declares.
fn link(
	engine: &Engine,
	module: &Module,
	methods: &HashMap<&'static str, Method>,
) -> Result<Linker<GuestState>, WasmWorkerError> {
	let mut linker = Linker::new(engine);
	for import in module.imports() {
		let unknown = || WasmWorkerError::UnknownImport {
			module: import.module().to_owned(),
			name: import.name().to_owned(),
		};
		if import.module() != IMPORT_MODULE {
			return Err(unknown());
		}
		let linked = match import.name() {
			RELEASE_IMPORT => linker.func_wrap(IMPORT_MODULE, RELEASE_IMPORT, release),
			READ_EVENT_IMPORT => linker.func_wrap(IMPORT_MODULE, READ_EVENT_IMPORT, read_event),
			LOG_IMPORT => linker.func_wrap(IMPORT_MODULE, LOG_IMPORT, log),
			FINISH_IMPORT => linker.func_wrap(IMPORT_MODULE, FINISH_IMPORT, finish),
			RANDOM_IMPORT => linker.func_wrap(IMPORT_MODULE, RANDOM_IMPORT, random),
			NOW_MILLIS_IMPORT => linker.func_wrap(IMPORT_MODULE, NOW_MILLIS_IMPORT, now_millis),
			MONOTONIC_MILLIS_IMPORT => {
				linker.func_wrap(IMPORT_MODULE, MONOTONIC_MILLIS_IMPORT, monotonic_millis)
			},
			SLEEP_IMPORT => linker.func_wrap(IMPORT_MODULE, SLEEP_IMPORT, sleep),
			CALL_ITEM_IMPORT => linker.func_wrap(IMPORT_MODULE, CALL_ITEM_IMPORT, call_item),
			CALL_END_IMPORT => linker.func_wrap(IMPORT_MODULE, CALL_END_IMPORT, call_end),
			name => {
				let (name, method) = methods.get_key_value(name).ok_or_else(unknown)?;
				let method = method.clone();
				linker.func_wrap(
					IMPORT_MODULE,
					name,
					move |caller: Caller<'_, GuestState>, pointer: u32, length: u32| {
						start_call(caller, method.clone(), pointer, length)
					},
				)
			},
		};
		linked.map_err(|error| WasmWorkerError::InvalidModule { reason: error.to_string() })?;
	}
	Ok(linker)
}

fn start_call(
	mut caller: Caller<'_, GuestState>,
	method: Method,
	pointer: u32,
	length: u32,
) -> Result<u32, wasmi::Error> {
	let request = read_guest(&caller, pointer, length)?;
	let state = caller.data_mut();
	let handle = open_handle(state)?;
	state.commands.push(Command::Start { handle, method, request });
	Ok(handle)
}

/// Give a new call or timer a handle, within [`MAX_CALLS_IN_FLIGHT`].
fn open_handle(state: &mut GuestState) -> Result<u32, wasmi::Error> {
	if state.calls_in_flight >= MAX_CALLS_IN_FLIGHT {
		return Err(wasmi::Error::new("too many calls in flight"));
	}
	let handle = state.next_handle;
	state.next_handle = handle
		.checked_add(1)
		.ok_or_else(|| wasmi::Error::new("call handles exhausted"))?;
	state.calls_in_flight += 1;
	Ok(handle)
}

fn sleep(mut caller: Caller<'_, GuestState>, millis: u64) -> Result<u32, wasmi::Error> {
	let state = caller.data_mut();
	let handle = open_handle(state)?;
	state.commands.push(Command::Sleep { handle, millis });
	Ok(handle)
}

fn random(
	mut caller: Caller<'_, GuestState>,
	pointer: u32,
	length: u32,
) -> Result<(), wasmi::Error> {
	if length > MAX_PAYLOAD_BYTES {
		return Err(wasmi::Error::new("random buffer too large"));
	}
	let memory = guest_memory(&caller)?;
	let start = pointer as usize;
	let buffer = memory
		.data_mut(&mut caller)
		.get_mut(start..start + length as usize)
		.ok_or_else(|| wasmi::Error::new("random buffer outside worker memory"))?;
	getrandom::getrandom(buffer).map_err(|error| wasmi::Error::new(error.to_string()))
}

fn now_millis() -> u64 {
	crate::unix_time::current_unix_millis()
}

fn monotonic_millis(caller: Caller<'_, GuestState>) -> u64 {
	u64::try_from(caller.data().loaded.elapsed().as_millis()).unwrap_or(u64::MAX)
}

fn call_item(
	caller: Caller<'_, GuestState>,
	call: u32,
	pointer: u32,
	length: u32,
) -> Result<(), wasmi::Error> {
	answer(caller, call, pointer, length, HostCallEvent::Item)
}

fn call_end(
	caller: Caller<'_, GuestState>,
	call: u32,
	pointer: u32,
	length: u32,
) -> Result<(), wasmi::Error> {
	answer(caller, call, pointer, length, HostCallEvent::End)
}

/// Queue one answer to a call of the host. The worker passes it on after the
/// entry returns, so the import never calls back into the guest.
fn answer(
	mut caller: Caller<'_, GuestState>,
	call: u32,
	pointer: u32,
	length: u32,
	event: fn(Vec<u8>) -> HostCallEvent,
) -> Result<(), wasmi::Error> {
	let payload = read_guest(&caller, pointer, length)?;
	caller.data_mut().commands.push(Command::Answer { call, event: event(payload) });
	Ok(())
}

fn release(mut caller: Caller<'_, GuestState>, handle: u32) {
	caller.data_mut().commands.push(Command::Release { handle });
}

fn read_event(mut caller: Caller<'_, GuestState>, pointer: u32) -> Result<(), wasmi::Error> {
	let memory = guest_memory(&caller)?;
	let payload = core::mem::take(&mut caller.data_mut().event_payload);
	let start = pointer as usize;
	memory
		.data_mut(&mut caller)
		.get_mut(start..start + payload.len())
		.ok_or_else(|| wasmi::Error::new("event buffer outside worker memory"))?
		.copy_from_slice(&payload);
	Ok(())
}

fn log(caller: Caller<'_, GuestState>, pointer: u32, length: u32) -> Result<(), wasmi::Error> {
	let line = read_guest_text(&caller, pointer, length)?;
	let state = caller.data();
	if state.log_fuel {
		let used = state
			.fuel_used
			.saturating_add(state.fuel_per_entry.saturating_sub(caller.get_fuel()?));
		(state.log)(&format!("fuel={used} {line}"));
	} else {
		(state.log)(&line);
	}
	Ok(())
}

fn finish(
	mut caller: Caller<'_, GuestState>,
	succeeded: u32,
	pointer: u32,
	length: u32,
) -> Result<(), wasmi::Error> {
	let outcome =
		if succeeded == 1 { Ok(()) } else { Err(read_guest_text(&caller, pointer, length)?) };
	caller.data_mut().finished = Some(outcome);
	Ok(())
}

fn read_guest(
	caller: &Caller<'_, GuestState>,
	pointer: u32,
	length: u32,
) -> Result<Vec<u8>, wasmi::Error> {
	if length > MAX_PAYLOAD_BYTES {
		return Err(wasmi::Error::new("payload too large"));
	}
	let start = pointer as usize;
	guest_memory(caller)?
		.data(caller)
		.get(start..start + length as usize)
		.map(<[u8]>::to_vec)
		.ok_or_else(|| wasmi::Error::new("payload outside worker memory"))
}

fn guest_memory(caller: &Caller<'_, GuestState>) -> Result<Memory, wasmi::Error> {
	caller
		.get_export(MEMORY_EXPORT)
		.and_then(Extern::into_memory)
		.ok_or_else(|| wasmi::Error::new("worker exports no memory"))
}

fn read_guest_text(
	caller: &Caller<'_, GuestState>,
	pointer: u32,
	length: u32,
) -> Result<String, wasmi::Error> {
	String::from_utf8(read_guest(caller, pointer, length)?)
		.map_err(|error| wasmi::Error::new(error.to_string()))
}

#[cfg(test)]
mod tests {
	use std::collections::BTreeSet;

	use super::*;
	use crate::{
		generated::wire_table::WIRE_TABLE,
		runtime::ProductRuntimeHost,
		test_support::{runtime_config, stub_platform, test_spawner},
	};

	/// Some methods a product never starts: the internal permission
	/// authorizations, the render stream and the Chat Extension v2 queries
	/// that the host opens.
	const NOT_PRODUCT_STARTED: [&str; 5] = [
		"permissions_authorize_remote_permission",
		"permissions_authorize_device_permission",
		"renderer_render",
		"chat_messages_query",
		"chat_user_action",
	];

	/// Sets its flag when the stream that holds it is dropped.
	struct DropFlag(Arc<std::sync::atomic::AtomicBool>);

	impl Drop for DropFlag {
		fn drop(&mut self) {
			self.0.store(true, std::sync::atomic::Ordering::SeqCst);
		}
	}

	#[test]
	fn a_released_subscription_ends_also_when_its_stream_ignores_the_cancellation() {
		use crate::versioned::preimage::{
			RemotePreimageLookupSubscribeError, RemotePreimageLookupSubscribeItem,
			RemotePreimageLookupSubscribeRequest,
		};
		let dropped = Arc::new(std::sync::atomic::AtomicBool::new(false));
		let flag = dropped.clone();
		let mut env = WasmEnv::new(Arc::new(()));
		env.subscription::<
			RemotePreimageLookupSubscribeRequest,
			RemotePreimageLookupSubscribeItem,
			RemotePreimageLookupSubscribeError,
			_,
		>("lookup", move |_, _, _| {
			let guard = DropFlag(flag.clone());
			// A stream that never ends and never reads the cancellation.
			let items = stream::pending().map(move |item| {
				let _ = &guard;
				item
			});
			futures::future::ready(Subscription::new(items)).boxed()
		});
		let method = env.methods.get("lookup").expect("linked").clone();
		let cancel = CancellationToken::default();
		let cx = CallContext::with_parts("wasm-1".to_string(), cancel.clone());
		let mut events = method(
			cx,
			RemotePreimageLookupSubscribeRequest::V1(
				crate::v01::RemotePreimageLookupSubscribeRequest { key: vec![1] },
			)
			.encode(),
		);

		let waiting = futures::executor::block_on(futures::future::poll_fn(|context| {
			Poll::Ready(events.poll_next_unpin(context).is_pending())
		}));
		cancel.cancel();
		let end = futures::executor::block_on(events.next()).map(|event| event.kind);
		drop(events);

		assert_eq!(
			(waiting, end, dropped.load(std::sync::atomic::Ordering::SeqCst)),
			(true, Some(EventKind::End), true)
		);
	}

	#[test]
	fn a_worker_can_import_every_method_a_product_starts_under_its_wire_name() {
		let host =
			ProductRuntimeHost::new(stub_platform(), runtime_config("worker.dot"), test_spawner());

		let env = WasmEnv::for_product(Arc::new(host));
		let linked: BTreeSet<_> = env.method_names().collect();
		let excluded: BTreeSet<_> = env.excluded_names().collect();

		for method in NOT_PRODUCT_STARTED {
			assert!(excluded.contains(method), "{method} must get no import");
		}
		assert!(linked.is_disjoint(&excluded));
		let every_method: BTreeSet<_> = WIRE_TABLE.iter().map(|entry| entry.method).collect();
		let accounted: BTreeSet<_> = linked.union(&excluded).copied().collect();
		assert_eq!(accounted, every_method);
	}
}
